import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

async function exportToObj() {
    console.log('Starting export...');

    // 1. Create the scene
    const root = createScene();

    // 2. Update world matrices to ensure all transforms are calculated
    root.updateMatrixWorld(true);

    // 3. Prepare Blender Z-up conversion matrix (-90 degrees X-rotation)
    const conversionMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);

    // 4. Create a container for baked meshes
    const exportContainer = new THREE.Group();

    root.traverse((obj) => {
        if (obj.isMesh) {
            if (obj.isInstancedMesh) {
                console.log(`Expanding InstancedMesh: ${obj.name || 'unnamed'} with ${obj.count} instances`);
                for (let i = 0; i < obj.count; i++) {
                    const instanceMatrix = new THREE.Matrix4();
                    obj.getMatrixAt(i, instanceMatrix);

                    // Combine world matrix and instance matrix
                    const worldMatrix = new THREE.Matrix4();
                    worldMatrix.multiplyMatrices(obj.matrixWorld, instanceMatrix);

                    // Apply Blender conversion
                    worldMatrix.premultiply(conversionMatrix);

                    // Clone and bake geometry
                    const geom = obj.geometry.clone();
                    geom.applyMatrix4(worldMatrix);

                    // Create a simple mesh with identity transform
                    const bakedMesh = new THREE.Mesh(geom);
                    exportContainer.add(bakedMesh);
                }
            } else {
                console.log(`Baking Mesh: ${obj.name || 'unnamed'}`);

                // Get world matrix and apply Blender conversion
                const worldMatrix = new THREE.Matrix4();
                worldMatrix.copy(obj.matrixWorld);
                worldMatrix.premultiply(conversionMatrix);

                // Clone and bake geometry
                const geom = obj.geometry.clone();
                geom.applyMatrix4(worldMatrix);

                // Create a simple mesh with identity transform
                const bakedMesh = new THREE.Mesh(geom);
                exportContainer.add(bakedMesh);
            }
        }
    });

    // 5. Export to OBJ format
    const exporter = new OBJExporter();
    const objString = exporter.parse(exportContainer);

    // 6. Write to file
    const outputDir = '/root/output';
    const outputPath = path.join(outputDir, 'object.obj');

    if (!fs.existsSync(outputDir)) {
        fs.mkdirSync(outputDir, { recursive: true });
    }

    fs.writeFileSync(outputPath, objString);
    console.log(`Successfully exported to ${outputPath}`);
}

exportToObj().catch(err => {
    console.error('Export failed:', err);
    process.exit(1);
});

